    "id": "us/NCE2/88.Trapped in a Mine",
    "book": "us",
    "group": "NCE2",
    "filename": "NCE2/88.Trapped in a Mine",
    "title": "Trapped in a Mine",
    "audioUrl": "NCE/NCE2/88.Trapped in a Mine.mp3",
