    "id": "us/NCE3/01.A Puma at Large",
    "book": "us",
    "group": "NCE3",
    "filename": "NCE3/01.A Puma at Large",
    "title": "A Puma at Large",
    "audioUrl": "NCE/NCE3/01.A Puma at Large.mp3",
