    "id": "us/NCE4/03.Matterhorn Man",
    "book": "us",
    "group": "NCE4",
    "filename": "NCE4/03.Matterhorn Man",
    "title": "Matterhorn Man",
    "audioUrl": "NCE/NCE4/03.Matterhorn Man.mp3",
