    "id": "us/NCE4/45.Of Men and Galaxies",
    "book": "us",
    "group": "NCE4",
    "filename": "NCE4/45.Of Men and Galaxies",
    "title": "Of Men and Galaxies",
    "audioUrl": "NCE/NCE4/45.Of Men and Galaxies.mp3",
